from taf.ue.plugin.mtk.data_transfer.datatransfer import MTKIperfUpLinkDataTransfer, MTKIperfDownLinkDataTransfer


class DataTransferFactory(object):
    def __init__(self, **kwargs):
        pass

    def create(self, **kwargs):
        pass


class MTKIperfUpLinkDataTransferFactory(DataTransferFactory):
    def __init__(self, ue=None):
        super(MTKIperfUpLinkDataTransferFactory, self).__init__()
        self._ue = ue

    def create(self, alias, dt_definition, configuration, throughput_checker, is_client_adb_shell=False,
               appserver=None, iperf_port=None):
        dt = MTKIperfUpLinkDataTransfer(alias=alias,
                                        dt_definition=dt_definition,
                                        configuration=configuration,
                                        checkthroughput=throughput_checker,
                                        ue=self._ue,
                                        is_client_adb_shell=is_client_adb_shell,
                                        appserver=appserver,
                                        iperf_port=iperf_port
                                        )
        return dt


class MTKIperfDownLinkDataTransferFactory(DataTransferFactory):
    def __init__(self, ue=None):
        super(MTKIperfDownLinkDataTransferFactory, self).__init__()
        self._ue = ue

    def create(self, alias, dt_definition, configuration, throughput_checker, is_server_adb_shell=False,
               appserver=None, iperf_port=None):
        dt = MTKIperfDownLinkDataTransfer(alias=alias,
                                          dt_definition=dt_definition,
                                          configuration=configuration,
                                          checkthroughput=throughput_checker,
                                          ue=self._ue,
                                          is_server_adb_shell=is_server_adb_shell,
                                          appserver=appserver,
                                          iperf_port=iperf_port
                                          )
        return dt
